package com.travbook.holidays.adapter.out.persistence;
import com.travbook.holidays.application.port.out.HolidayStore;
import com.travbook.holidays.domain.model.Holiday.*;
import com.travbook.shared.domain.DomainFailure;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
public final class JdbcHolidays implements HolidayStore{
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final Clock clock;
 public JdbcHolidays(JdbcClient jdbc,TransactionTemplate tx,ObjectMapper json,Clock clock){this.jdbc=jdbc;this.tx=tx;this.json=json;this.clock=clock;}
 private DomainFailure missing(){return new DomainFailure(DomainFailure.Code.NOT_FOUND,"Holiday resource not found.");}
 public Optional<UUID> replay(UUID owner,String operation,String key,String fingerprint){return jdbc.sql("select fingerprint,resource_id from holiday_command where customer_id=:owner and operation=:operation and command_key=:key").param("owner",owner).param("operation",operation).param("key",key).query((r,n)->{if(!r.getString(1).equals(fingerprint))throw new DomainFailure(DomainFailure.Code.IDEMPOTENCY_CONFLICT,"This key was used for different holiday inputs.");return r.getObject(2,UUID.class);}).optional();}
 private boolean claim(UUID owner,String operation,String key,String fingerprint,UUID resource){return jdbc.sql("insert into holiday_command(customer_id,operation,command_key,fingerprint,resource_id) values(:owner,:operation,:key,:fingerprint,:resource) on conflict(customer_id,operation,command_key) do nothing").param("owner",owner).param("operation",operation).param("key",key).param("fingerprint",fingerprint).param("resource",resource).update()==1;}
 public Quote quote(UUID owner,UUID id){return jdbc.sql("select payload::text from holiday_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(p->json.readValue(p,Quote.class)).orElseThrow(this::missing);}
 public Quote save(Quote q,String key,String fingerprint,UUID correlation){return tx.execute(t->{if(!claim(q.owner(),"QUOTE",key,fingerprint,q.id()))return quote(q.owner(),replay(q.owner(),"QUOTE",key,fingerprint).orElseThrow());q.valid(clock.instant());jdbc.sql("insert into holiday_quote(id,customer_id,created_at,expires_at,payload) values(:id,:owner,:at,:until,cast(:payload as jsonb))").param("id",q.id()).param("owner",q.owner()).param("at",Timestamp.from(q.createdAt())).param("until",Timestamp.from(q.expiresAt())).param("payload",json.writeValueAsString(q)).update();event(q.id(),"HolidayQuoteCreated",correlation);return q;});}
 public UUID enquiryForQuote(UUID owner,UUID quote){quote(owner,quote);return jdbc.sql("select id from holiday_enquiry where quote_id=:quote and customer_id=:owner").param("quote",quote).param("owner",owner).query(UUID.class).optional().orElse(null);}
 public Enquiry enquiry(UUID owner,UUID id){return jdbc.sql("select payload::text from holiday_enquiry where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(p->json.readValue(p,Enquiry.class)).orElseThrow(this::missing);}
 public Enquiry saveEnquiry(UUID owner,UUID quoteId,Contact contact,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID id=UUID.randomUUID();if(!claim(owner,"ENQUIRY",key,fingerprint,id))return enquiry(owner,replay(owner,"ENQUIRY",key,fingerprint).orElseThrow());jdbc.sql("select id from holiday_quote where id=:id and customer_id=:owner for update").param("id",quoteId).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);var q=quote(owner,quoteId);q.valid(clock.instant());if(q.travelPackage().fulfilment()!=Fulfilment.ENQUIRY)throw new DomainFailure(DomainFailure.Code.BOOKING_CONFLICT,"This package is marked for direct fulfilment; enquiry workflow is not supported.");if(jdbc.sql("select count(*) from holiday_enquiry where quote_id=:id").param("id",quoteId).query(Integer.class).single()>0)throw new DomainFailure(DomainFailure.Code.BOOKING_CONFLICT,"This quote already has an enquiry. Recover the original request.");var result=new Enquiry(id,owner,q,contact,"RECORDED_LOCALLY",clock.instant(),"MOCK");jdbc.sql("insert into holiday_enquiry(id,quote_id,customer_id,payload) values(:id,:quote,:owner,cast(:payload as jsonb))").param("id",id).param("quote",quoteId).param("owner",owner).param("payload",json.writeValueAsString(result)).update();event(id,"HolidayEnquiryRecorded",correlation);return result;});}
 private void event(UUID aggregate,String type,UUID correlation){var envelope=Map.of("eventId",UUID.randomUUID(),"aggregateId",aggregate,"aggregateVersion",1,"schemaVersion",1,"eventType",type,"occurredAt",clock.instant(),"correlationId",correlation,"causationId",UUID.nameUUIDFromBytes((aggregate+":"+type).getBytes(java.nio.charset.StandardCharsets.UTF_8)),"producer","holidays","mode","MOCK");jdbc.sql("insert into holiday_outbox(id,aggregate_id,envelope) values(:id,:aggregate,cast(:body as jsonb))").param("id",envelope.get("eventId")).param("aggregate",aggregate).param("body",json.writeValueAsString(envelope)).update();}
}
